// Optional story choices are campaign data; onboarding completion remains a device preference.
var clubStoryEvent=null,clubStoryOpener=null,clubStoryExpected=null;
const storyRelationNames={board:'구단주',coach:'코치',captain:'선수단',rookie:'유망주',fans:'팬'};
function storyMissionText(m){return m.year+'시즌 리그 '+m.end+'경기까지 · 출전 '+m.minutes+'/'+m.target+'분 · '+{active:'약속 진행 중',fulfilled:'약속을 지켰습니다',missed:'출전 약속을 지키지 못했습니다'}[m.status];}
function storyPromiseMarkup(m){
 const stateText=!m.slot?'현재 선수단에 없습니다.':!m.available?'현재 출전할 수 없습니다. 몸 상태와 출전 조건을 확인하세요.':(m.starting?'현재 선발':'현재 후보')+' · 체력 '+Math.round(m.energy);
 return '<section class="story-promise" aria-label="출전 약속 진행"><strong>'+escapeText(m.name)+'과의 출전 약속</strong><p>'+escapeText(storyMissionText(m))+'</p><progress max="'+m.target+'" value="'+Math.min(m.target,m.minutes)+'" aria-label="확정 출전 '+m.minutes+'분 / 목표 '+m.target+'분"></progress><small>'+(m.status==='active'?'남은 리그 '+m.remainingGames+'경기 · '+m.remainingMinutes+'분 필요 · ':'')+escapeText(stateText)+'</small><ol class="story-promise-games" aria-label="약속한 두 리그 경기">'+m.games.map(g=>'<li><span>리그 '+g.round+'R · '+escapeText(g.opponent?S.club(g.opponent).short:'상대 확인 대기')+'</span><strong>'+(g.confirmed?g.minutes+'분 출전':'경기 대기')+'</strong></li>').join('')+'</ol>'+(m.livePending?'<p class="story-promise-live" role="status">현재 경기 '+m.liveMinutes+'분 출전 · 결과 확정 후 약속에 반영됩니다.</p>':m.competition!=='league'&&m.status==='active'?'<p class="story-promise-live">컵·유럽 경기 출전은 리그 출전 약속에 포함되지 않습니다.</p>':'')+'<div>'+(m.slot&&m.status==='active'?'<button type="button" data-story-plan>선발·교체 계획 확인</button>':'')+(m.followupReady?'<button type="button" data-story-event="'+m.event+'">약속 후속 면담</button>':'')+'</div></section>';
}
function storyInboxPriority(pending){return [...pending].sort((a,b)=>(b.step===1)-(a.step===1)||b.round-a.round||Number(b.key?.startsWith('signing-'))-Number(a.key?.startsWith('signing-'))||a.id.localeCompare(b.id));}
function renderClubStory(){
 if(view!=='club')return;const host=$('club-story-panel'),d=ClubStory.read(season),inbox=storyInboxPriority(d.pending),next=inbox[0],mission=d.promises.filter(m=>m.current).at(-1);
 host.innerHTML='<div class="story-heading"><div><small>구단 이야기</small><h2>감독님께 도착한 대화</h2></div><span>'+d.pending.length+'건 대기</span></div><p>'+(next?escapeText(next.speaker)+'에게서 새로운 이야기가 도착했습니다. 다음 경기 전에 들어보세요.':'이번 대화를 모두 마쳤습니다. 경기 결과와 시즌 진행에 따라 다음 이야기가 도착합니다.')+'</p>'+(next?'<button type="button" id="club-story-open" class="primary">'+escapeText(next.title)+(next.step===1?' · 대화 이어가기':' · 대화하기')+'</button>':'')+(inbox.length>1?'<div class="story-recent" aria-label="최근 도착한 대화">'+inbox.slice(1,3).map(e=>'<button type="button" class="secondary" data-story-event="'+e.id+'">'+escapeText(e.title)+'<small>'+escapeText(e.speaker)+' · '+e.round+'경기 이후'+(e.step===1?' · 대화 진행 중':'')+'</small></button>').join('')+'</div>':'')+'<div class="story-relations">'+Object.entries(d.relationships).map(([key,value])=>'<span>'+storyRelationNames[key]+' <b>'+value+'</b></span>').join('')+'</div>'+(mission?storyPromiseMarkup(mission):'')+'<details><summary>대기 이벤트와 지난 대화</summary><div class="story-event-list">'+inbox.map(e=>'<button type="button" data-story-event="'+e.id+'">'+escapeText(e.title)+'<small>'+escapeText(e.speaker)+' · '+e.round+'경기 이후</small></button>').join('')+'</div><ol class="story-history">'+d.history.slice(-6).reverse().map(h=>'<li><button type="button" data-story-event="'+h.id+'">'+escapeText(h.title)+' · 다시 읽기</button><span>'+h.year+'시즌 · '+h.round+'경기 완료 시점 · '+escapeText(h.actor)+'</span><small>'+(h.choice==='commit'?'방향을 지키겠다고 약속했습니다.':'조건을 설명하고 함께 점검하기로 했습니다.')+'</small>'+(h.mission?'<small>'+escapeText(storyMissionText(h.mission))+'</small>':'')+'</li>').join('')+'</ol></details><small>선택은 관계와 후속 대사에 남습니다. 출전 약속은 확정한 리그 경기 기록으로 확인합니다.</small>';
 host.onclick=event=>{const plan=event.target.closest('[data-story-plan]');if(plan){const player=Object.values(state?.players||{}).find(p=>p.identity===mission?.identity);if(player)selected=state.lineup.includes(player.id)?player.id:null;setView('match');openMatchPopup(state?.phase==='prep'?'tactics':'roster',plan);return;}const b=event.target.closest('[data-story-event]');if(b)openClubStory(b.dataset.storyEvent,b);else if(event.target.closest('#club-story-open'))openClubStory(next.id,$('club-story-open'));};
}
function openClubStory(event,opener=document.activeElement){
 if(typeof practiceSession!=='undefined'&&practiceSession){notify('전술 연습을 마친 뒤 구단 대화를 확인하세요.');return;}
 if(!ClubStory.scene(season,event))return;pauseForPlanning();save();clubStoryEvent=event;clubStoryOpener=opener;renderClubStoryDialog();$('club-story-dialog').showModal();
}
function renderClubStoryDialog(){
 const d=ClubStory.scene(season,clubStoryEvent);if(!d){$('club-story-dialog').close();return;}clubStoryExpected=ClubStory.fingerprint(season);
 const host=$('club-story-dialog'),first=d.answered[0],firstIndex=first?['listen','bold','practical'].indexOf(first.choice):-1,action=d.year!==season.year?null:['late-goal','outnumbered-result','shape','runin','halfway','marathon','promotion-race','final-push','signing-deadball','three-losses'].includes(d.key)?'tactics':['bench-hero','rookie','promise-kept','promise-missed','signing-welcome','signing-debut'].includes(d.key)?'roster':d.key==='window'?'market':['medical','fans','community','signing-goal','five-unbeaten','cup-night'].includes(d.key)?'squad':d.key==='tier'||d.key==='arrival'?'journey':null;

 const artKind=['arrival','tier'].includes(d.key)?'arrival':d.relation;
 const portrait=F.identityProfile(d.actor),past=(first?'<p class="story-bubble manager"><b>감독</b>'+escapeText(d.options[firstIndex])+'</p><p class="story-bubble"><b>'+escapeText(d.name)+'</b>'+escapeText(d.reaction)+'</p>':'')+(d.reply?'<p class="story-bubble"><b>'+escapeText(d.name)+'</b>'+escapeText(d.question)+'</p><p class="story-bubble manager"><b>감독</b>'+escapeText(d.finalLabel)+'</p>':'');
 host.innerHTML='<header class="story-dialog-head">'+ClubArt.story(artKind)+'<div><small>구단 이야기 · '+d.year+'시즌 · '+(d.step===2?'대화 완료':(d.step+1)+'/2')+'</small><h2 id="club-story-title" tabindex="-1">'+escapeText(d.title)+'</h2>'+(d.year!==season.year?'<small>지난 시즌 기록 · 읽기 전용</small>':'')+'</div><button type="button" data-story-close aria-label="구단 대화 닫기">닫기</button></header><div class="story-speaker">'+(portrait?Portraits.html(portrait):d.relation==='coach'?StaffPortraits.html({name:d.name}):'<span class="story-speaker-icon" aria-hidden="true">'+{board:'▣',captain:'●',rookie:'★',fans:'⚑'}[d.relation]+'</span>')+'<div><b>'+escapeText(d.name)+'</b><small>'+escapeText(d.speaker)+' · '+escapeText(d.memory)+'</small></div></div><div class="story-conversation" tabindex="0" aria-label="현재 대화와 지난 이야기"><p class="story-scene-intro" aria-hidden="true">'+escapeText(d.scene)+'</p><p class="story-bubble story-current"><b>'+escapeText(d.name)+'</b>'+escapeText(d.reply||d.question)+'</p><details class="story-context"><summary>장면 이어 읽기 · 지난 대화</summary><p class="story-scene">'+escapeText(d.scene)+'</p>'+past+'</details>'+(d.mission?'<p class="story-mission">'+escapeText(storyMissionText(d.mission))+'</p>':'')+'</div><div class="story-choices" aria-label="감독의 대답">'+d.choices.map(c=>'<button type="button" class="secondary" data-story-choice="'+c.id+'" '+(c.disabled?'disabled':'')+'>'+escapeText(c.label)+(c.disabled?' · '+escapeText(c.reason||'리그 킥오프 전에 가능'):'')+'</button>').join('')+'</div>'+(d.step===2?'<p class="story-complete" role="status">대화 기록 · 현재 '+storyRelationNames[d.relation]+' 관계 '+d.relationScore+'</p>'+(action?'<button type="button" class="primary" data-story-action="'+action+'">'+{tactics:'상대·전술·체력 확인하기',roster:'선발·교체 출전 계획 확인하기',market:'영입 보고서 확인하기',squad:'선수단과 컨디션 확인하기',journey:'승격 목표와 시즌 진행 확인하기'}[action]+'</button>':''):'')+'<footer><button type="button" class="secondary" data-story-close>'+(d.step===2?'감독실로 돌아가기':'나중에 이어서 대화하기')+'</button><small>경기는 직접 재개할 때 이어집니다.</small></footer>';

 host.onclick=event=>{const choice=event.target.closest('[data-story-choice]'),close=event.target.closest('[data-story-close]'),go=event.target.closest('[data-story-action]');if(close){host.close();return;}if(go){host.close();const target=go.dataset.storyAction;if(['tactics','roster'].includes(target)&&state){setView('match');openMatchPopup(target,$('primary'));}else if(target==='journey')setView('club');else setView(target==='market'?'market':'squad');return;}if(choice){try{ClubStory.choose(season,d.id,d.step,choice.dataset.storyChoice,clubStoryExpected);save();render();renderClubStoryDialog();$('club-story-title').focus({preventScroll:true});}catch(error){notify(error.message);renderClubStoryDialog();}}};
}
const storyPanel=document.createElement('section');storyPanel.id='club-story-panel';$('manager-journey').after(storyPanel);
const storyDialog=document.createElement('dialog');storyDialog.id='club-story-dialog';storyDialog.setAttribute('aria-labelledby','club-story-title');document.body.append(storyDialog);
storyDialog.addEventListener('close',()=>{clubStoryEvent=null;clubStoryExpected=null;if(clubStoryOpener?.isConnected&&!clubStoryOpener.closest('dialog'))clubStoryOpener.focus({preventScroll:true});else $('club-story-open')?.focus({preventScroll:true});clubStoryOpener=null;});
const storyOriginalJourney=renderManagerJourney;renderManagerJourney=function(){storyOriginalJourney();renderClubStory();};
